// Mendapatkan data9 dan data2
let arr = getPrincipalCollection(['data9', 'data2']);  
let noSls = getValue('r501a'); // Mengambil nilai dari r501a yang berupa array
let data = "0"; // Variabel untuk menyimpan hasil

if (noSls) {
    // Gabungkan data9 dan data2 berdasarkan indeks
    let combinedArr = arr.data9.map((value, index) => ({ data9: value, data2: arr.data2[index] }));

    // Filter elemen di mana data9 sama dengan noSls[0].value
    let array1sls = combinedArr.filter(i => i.data9 === noSls);

    // Ambil data2 dari hasil filter
    let found = array1sls.map((element) => element.data2);

    // Konversi elemen data2 menjadi angka jika mungkin, jika bukan angka biarkan string
    let newarr = found.map(i => isNaN(i) ? i : Number(i));

    // Cari nilai maksimum dari array yang mungkin berisi angka dan string
    let maxNumber = newarr.reduce((max, current) => {
        // Konversi current dan max ke angka untuk perbandingan
        let currentNumber = parseInt(current, 10);
        let maxNumber = parseInt(max, 10);

        // Jika current lebih besar dari max, update max
        if (!isNaN(currentNumber) && currentNumber > maxNumber) {
            return current;
        }

        // Jika tidak, tetap gunakan max
        return max;
    }, newarr[0]);

    // Pastikan nilai maksimum tetap string jika awalnya string dengan leading zeros
    if (typeof maxNumber === 'string' && maxNumber.startsWith('0')) {
        data = maxNumber;
    } else if (maxNumber !== undefined) {
        data = maxNumber.toString();
    }
}

data;

